cd /tmp/vally-eval-trial-JsvQeX && P=.copilot-tracking/skraft-plans/pricing && D=2026-10-07 && mkdir -p $P/features $P/details/$D tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount $P/evidence/$D/discount
cat > $P/features/pricing-loyalty-discount.feature <<'E'
@loyalty-discount
Feature: Loyalty discount on the basket

  A returning customer's loyalty tier lowers the amount charged at checkout.
  The reduction is never larger than the exact share and always lands on a whole cent in the customer's favour.

  @happy-path @smoke
  Scenario: Bronze customer is charged the Bronze price
    Given a returning customer in the Bronze tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9500 cents

  @happy-path
  Scenario: Silver customer is charged the Silver price
    Given a returning customer in the Silver tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 9000 cents

  @happy-path
  Scenario: Gold customer is charged the Gold price
    Given a returning customer in the Gold tier
    When a basket subtotal of 10000 cents is priced
    Then the customer is charged 8500 cents

  @edge-case
  Scenario: Bronze customer's reduction lands on a whole cent in their favour
    Given a returning customer in the Bronze tier
    When a basket subtotal of 7 cents is priced
    Then the customer is charged 7 cents
E
cat > tests/CheckoutPricing.UnitTest/Features/LoyaltyDiscount/LoyaltyDiscountAcceptanceTests.cs <<'E'
using CheckoutPricing.Application;
using CheckoutPricing.Domain;

namespace CheckoutPricing.UnitTest.Features.LoyaltyDiscount;

public class LoyaltyDiscountAcceptanceTests
{
    [Theory]
    // Bronze customer is charged the Bronze price
    [InlineData(LoyaltyTier.Bronze, 10000, 9500)]
    public void Returning_customer_is_charged_the_price_of_their_loyalty_tier(
        LoyaltyTier tier, int subtotalCents, int expectedChargedCents)
    {
        var pricing = new CalculateLoyaltyDiscount();

        var quote = pricing.Handle(new CalculateLoyaltyDiscountQuery(subtotalCents, tier));

        Assert.Equal(expectedChargedCents, quote.TotalCents);
    }
}
E
git rev-parse HEAD
dotnet build 2>&1 | tail -3
E=$P/evidence/$D/discount
dotnet test tests/CheckoutPricing.UnitTest --filter "FullyQualifiedName~LoyaltyDiscountAcceptanceTests" > $E/acceptance-red.stdout 2>&1; echo $? > $E/acceptance-red.exit; git rev-parse HEAD > $E/acceptance-red.rev; cat $E/acceptance-red.exit; grep -E "Assert|Expected|Actual|Failed|error" $E/acceptance-red.stdout | head

